import base64,json,os,pathlib,subprocess,time
root=pathlib.Path('/mnt/afs/260010165/behavior_1k/rlinf_adapter_20261023/retry07')
status=json.loads((root/'results/status.json').read_text())
assert status.get('stage')=='baseline' and status.get('state')=='running',status
matches=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try: args=(p/'cmdline').read_bytes().split(b'\0')
 except (PermissionError,FileNotFoundError):continue
 if str(root/'run/rollout.py').encode() in args and b'jax' in args:matches.append(p)
assert len(matches)==1,matches
pid=matches[0]
env=dict(item.split(b'=',1) for item in (pid/'environ').read_bytes().split(b'\0') if b'=' in item)
env={k.decode():v.decode() for k,v in env.items()}
env.update(JAX_PLATFORMS='cuda',JAX_DEFAULT_MATMUL_PRECISION='highest',XLA_PYTHON_CLIENT_PREALLOCATE='false',XLA_PYTHON_CLIENT_MEM_FRACTION='0.5')
out=root/'results/gpu_fp32_probe'
out.mkdir(exist_ok=False)
script=out/'probe.py'
script.write_bytes(base64.b64decode(''))
plan=json.loads((root/'run/plan.json').read_text())
with (out/'run.log').open('x') as log:
 child=subprocess.Popen(['timeout','--signal=TERM','--kill-after=30s','900s',plan['runtime']+'/envs/b1k-pi05/bin/python',str(script)],env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True,cwd=root)
receipt={'pid':child.pid,'baseline_pid':int(pid.name),'started_at':time.time(),'max_seconds':900,'additional_gpu':0,'root':str(out)}
(out/'launch.json').write_text(json.dumps(receipt,indent=2)+'\n')
print('B1KPROBE_BEGIN'+base64.b64encode(json.dumps(receipt).encode()).decode()+'B1KPROBE_END',flush=True)
